    if push:
        if not repo:
            raise click.ClickException("--push needs --repo org/name")
        te.push_to_hub(rows, repo)
        targets.append(f"hf.co/datasets/{repo}")
    click.echo(f"exported {len(rows)} row(s) -> {', '.join(targets)}")


